<?php

declare(strict_types=1);

require_once __DIR__.'/../../../../config/database.php';require_once __DIR__.'/../../../../app/Http/JsonResponse.php';require_once __DIR__.'/../../../../app/Http/Request.php';require_once __DIR__.'/../../../../app/Auth/Authorization.php';require_once __DIR__.'/../../../../app/Auth/ApiAuth.php';
floodguardRequireMethod('GET');$user=floodguardRequireApiUser($pdo,'reports.view_own');$id=filter_var($_GET['id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if($id===false)floodguardJsonResponse(422,['success'=>false,'message'=>'Valid report id required.']);
try{$stmt=$pdo->prepare('SELECT id,report_number,location_description,latitude,longitude,flood_description,immediate_danger,status,submitted_at,reviewed_at,decision_reason,updated_at FROM flood_reports WHERE id=:id AND reporter_user_id=:user LIMIT 1');$stmt->execute([':id'=>$id,':user'=>$user['id']]);$report=$stmt->fetch();if(!$report)floodguardJsonResponse(404,['success'=>false,'message'=>'Flood report not found.']);$history=$pdo->prepare('SELECT from_status,to_status,reason,changed_at FROM flood_report_status_history WHERE flood_report_id=:id ORDER BY changed_at,id');$history->execute([':id'=>$id]);$report['status_history']=$history->fetchAll();$photo=$pdo->prepare('SELECT COUNT(*) FROM flood_report_photos WHERE flood_report_id=:id');$photo->execute([':id'=>$id]);$report['has_photo']=(int)$photo->fetchColumn()>0;floodguardJsonResponse(200,['success'=>true,'data'=>$report]);}catch(Throwable $e){error_log('[Resident report show] '.$e->getMessage());floodguardJsonResponse(500,['success'=>false,'message'=>'Unable to load the flood report.']);}
